[CmdletBinding()]
param(
    [ValidateSet('gui','console','check','pack')][string]$Mode = 'gui',
    [switch]$ExtractOnly
)
$ErrorActionPreference = 'Stop'
if ($env:OS -ne 'Windows_NT') { throw 'Windows is required.' }
$bytes = [Convert]::FromBase64String('')
$sha = [Security.Cryptography.SHA256]::Create()
try { $hash = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-', '') }
finally { $sha.Dispose() }
if ($hash -ne '9CEB0E02899EB6C17A07F4C9F85E8DBC32383C05C3CF0D0513C86FE2D60EAFDD') { throw 'Embedded batch integrity check failed.' }
$folder = Join-Path $env:LOCALAPPDATA ('DSC-Signer-Launcher\' + [guid]::NewGuid().ToString('N'))
[void][IO.Directory]::CreateDirectory($folder)
$batch = Join-Path $folder 'DSC_Signer_OneClick_Fix.bat'
[IO.File]::WriteAllBytes($batch, $bytes)
Write-Host "Saved DSC Signer tool: $batch"
if ($ExtractOnly) { return }
$sys = Join-Path $env:SystemRoot 'System32'
if (Test-Path -LiteralPath (Join-Path $env:SystemRoot 'Sysnative\cmd.exe')) { $sys = Join-Path $env:SystemRoot 'Sysnative' }
$arguments = '/d /s /c ""' + $batch + '" ' + $Mode + '"'
$launch = @{ FilePath = (Join-Path $sys 'cmd.exe'); ArgumentList = $arguments; WorkingDirectory = $folder; PassThru = $true; Wait = $true }
if ($Mode -eq 'gui') { $launch.WindowStyle = 'Hidden' } else { $launch.NoNewWindow = $true }
# Retain the file so the original application can restart with administrator rights.
$process = Start-Process @launch
if ($process.ExitCode -ne 0) { throw "DSC Signer exited with code $($process.ExitCode)." }